<?php require_once __DIR__.'/../app/App.php'; Auth::requirePlatform(); $api=App::api(); $error=''; try{if($_SERVER['REQUEST_METHOD']==='POST'){Auth::platformApi($api,'PATCH','/api/v1/platform/tenants/'.(int)$_POST['id'].'/status',['status'=>$_POST['status']]);} $data=Auth::platformApi($api,'GET','/api/v1/platform/tenants');$tenants=$data['tenants']??[];}catch(Throwable $e){$error=$e->getMessage();$tenants=[];} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Platform Tenants</title><link rel="stylesheet" href="../Assets/css/app.css"><link rel="stylesheet" href="../Assets/css/admin.css"></head><body class="platform-page"><main><h1>Tenants</h1><p>Manage organizations on PassNow.</p><?php if($error):?><p class="error"><?=htmlspecialchars($error)?></p><?php endif?><table class="tenant-table"><tr><th>Organization</th><th>Slug</th><th>Status</th><th>Created</th><th>Action</th></tr><?php foreach($tenants as $t):?><tr><td><?=htmlspecialchars($t['name'])?></td><td><?=htmlspecialchars($t['slug'])?></td><td><span class="status-<?=htmlspecialchars($t['status'])?>"><?=htmlspecialchars($t['status'])?></span></td><td><?=htmlspecialchars((string)$t['created_at'])?></td><td><form method="post"><input type="hidden" name="id" value="<?= (int)$t['id']?>"><?php if($t['status']==='active'):?><input type="hidden" name="status" value="suspended"><button data-confirm="Suspend this tenant?">Suspend</button><?php else:?><input type="hidden" name="status" value="active"><button data-confirm="Activate this tenant?">Activate</button><?php endif?></form></td></tr><?php endforeach?></table></main><script src="../Assets/js/admin.js"></script></body></html>